const V2_CSS = `
@keyframes v2-scenein { from { opacity: 0; transform: scale(1.015); } to { opacity: 1; transform: scale(1); } }
@keyframes v2-caption { 0% { opacity: 0; transform: translateY(12px); } 8% { opacity: 1; transform: translateY(0); } 90% { opacity: 1; } 100% { opacity: 0; transform: translateY(-4px); } }
@keyframes v2-twinkle { 0%,100% { opacity: 0.15; } 50% { opacity: 0.95; } }
@keyframes v2-drift { 0%,100% { transform: translate(0,0); } 50% { transform: translate(-16px,7px); } }
@keyframes v2-cape { 0%,100% { transform: rotate(0deg); } 30% { transform: rotate(3.5deg); } 60% { transform: rotate(-5deg); } 82% { transform: rotate(2deg); } }
@keyframes v2-ball { 0% { transform: translateY(0) scale(1,1); } 12% { transform: translateY(-108px) scale(0.96,1.04); } 24% { transform: translateY(0) scale(1.14,0.84); } 38% { transform: translateY(-72px) scale(0.98,1.02); } 52% { transform: translateY(0) scale(1.09,0.91); } 66% { transform: translateY(-34px) scale(1,1); } 78% { transform: translateY(0) scale(1.05,0.95); } 100% { transform: translateY(0) scale(1,1); } }
@keyframes v2-shadow { 0%,100% { transform: scaleX(1); opacity: 0.5; } 12% { transform: scaleX(0.58); opacity: 0.32; } 24% { transform: scaleX(1.16); opacity: 0.55; } 38% { transform: scaleX(0.72); opacity: 0.36; } 52% { transform: scaleX(1.1); opacity: 0.52; } 66% { transform: scaleX(0.88); opacity: 0.42; } 100% { transform: scaleX(1); opacity: 0.5; } }
@keyframes v2-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
@keyframes v2-steam { 0% { transform: translateY(0); opacity: 0; } 30% { opacity: 0.5; } 100% { transform: translateY(-26px); opacity: 0; } }
@keyframes v2-beam { 0%,100% { opacity: 0.5; } 50% { opacity: 0.85; } }
`;

/* 确定性随机（噪点/材质纹理生成） */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* ================================================================== */
/* 材质系统（常驻 defs）                                                */
/* ================================================================== */
function MaterialDefs({ theme }: any) {
  const rnd = mulberry32(2024);
  const dots = Array.from({ length: 46 }).map(() => ({
    x: Math.floor(rnd() * 120),
    y: Math.floor(rnd() * 120),
    r: rnd() > 0.7 ? 1.6 : 1,
    o: 0.25 + rnd() * 0.5,
  }));
  return (
    <defs>
      {/* 夜空 */}
      <radialGradient id="v4-sky" cx="50%" cy="26%" r="95%">
        <stop offset="0%" stopColor={theme.category.purple} stopOpacity="1" />
        <stop offset="45%" stopColor={theme.category.blue} stopOpacity="0.75" />
        <stop offset="100%" stopColor={theme.bg.chrome} stopOpacity="1" />
      </radialGradient>
      {/* 黎明天空 */}
      <linearGradient id="v4-dawn" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={theme.category.blue} stopOpacity="0.85" />
        <stop offset="42%" stopColor={theme.category.purple} stopOpacity="0.7" />
        <stop offset="68%" stopColor={theme.category.orange} stopOpacity="0.55" />
        <stop offset="100%" stopColor={theme.category.yellow} stopOpacity="0.35" />
      </linearGradient>
      {/* 卧室墙面（受月光） */}
      <linearGradient id="v4-wall" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stopColor={theme.fill.primary} stopOpacity="1" />
        <stop offset="60%" stopColor={theme.fill.secondary} stopOpacity="1" />
        <stop offset="100%" stopColor={theme.fill.tertiary} stopOpacity="1" />
      </linearGradient>
      {/* 木纹 */}
      <linearGradient id="v4-wood" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={theme.category.purple} stopOpacity="0.75" />
        <stop offset="50%" stopColor={theme.category.purple} stopOpacity="0.55" />
        <stop offset="100%" stopColor={theme.bg.chrome} stopOpacity="0.9" />
      </linearGradient>
      {/* 舞台地板 */}
      <linearGradient id="v4-floor" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stopColor={theme.bg.chrome} stopOpacity="1" />
        <stop offset="50%" stopColor={theme.category.purple} stopOpacity="0.45" />
        <stop offset="100%" stopColor={theme.bg.chrome} stopOpacity="1" />
      </linearGradient>
      {/* 金属（麦克风/灯架） */}
      <linearGradient id="v4-metal" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stopColor={theme.text.secondary} stopOpacity="1" />
        <stop offset="45%" stopColor={theme.text.primary} stopOpacity="0.9" />
        <stop offset="100%" stopColor={theme.text.tertiary} stopOpacity="1" />
      </linearGradient>
      {/* 玻璃反光 */}
      <linearGradient id="v4-glass" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stopColor={theme.category.cyan} stopOpacity="0.28" />
        <stop offset="45%" stopColor={theme.bg.chrome} stopOpacity="0.12" />
        <stop offset="100%" stopColor={theme.category.cyan} stopOpacity="0.3" />
      </linearGradient>
      {/* 体积光（月光/舞台光） */}
      <linearGradient id="v4-beam" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={theme.category.yellow} stopOpacity="0.5" />
        <stop offset="70%" stopColor={theme.category.yellow} stopOpacity="0.12" />
        <stop offset="100%" stopColor={theme.category.yellow} stopOpacity="0" />
      </linearGradient>
      {/* 车流光轨 */}
      <linearGradient id="v4-trail" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stopColor={theme.category.red} stopOpacity="0.9" />
        <stop offset="100%" stopColor={theme.category.yellow} stopOpacity="0.15" />
      </linearGradient>
      {/* 雾 */}
      <linearGradient id="v4-fog" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={theme.bg.chrome} stopOpacity="0" />
        <stop offset="100%" stopColor={theme.bg.chrome} stopOpacity="0.85" />
      </linearGradient>
      {/* 噪点材质（pattern，确定性） */}
      <pattern id="v4-noise" width="120" height="120" patternUnits="userSpaceOnUse">
        {dots.map((d, i) => (
          <circle key={i} cx={d.x} cy={d.y} r={d.r} fill={theme.text.primary} opacity={d.o} />
        ))}
      </pattern>
      {/* 球场线纹理 */}
      <pattern id="v4-court" width="48" height="48" patternUnits="userSpaceOnUse">
        <path d="M 48 0 L 0 0 0 48" fill="none" stroke={theme.text.secondary} strokeWidth="1" opacity="0.28" />
      </pattern>
      {/* 滤镜 */}
      <filter id="v4-glow"><feGaussianBlur stdDeviation="9" /></filter>
      <filter id="v4-soft"><feGaussianBlur stdDeviation="3" /></filter>
      <filter id="v4-shadow" x="-40%" y="-40%" width="180%" height="180%">
        <feDropShadow dx="4" dy="8" stdDeviation="6" floodColor={theme.bg.chrome} floodOpacity="0.55" />
      </filter>
      <filter id="v4-shadowsm" x="-30%" y="-30%" width="160%" height="160%">
        <feDropShadow dx="2" dy="4" stdDeviation="3" floodColor={theme.bg.chrome} floodOpacity="0.45" />
      </filter>
    </defs>
  );
}

/* 噪点覆盖层（胶片颗粒质感） */
function NoiseLayer({ theme, o = 0.05 }: any) {
  return <rect width="960" height="540" fill="url(#v4-noise)" opacity={o} />;
}

