/* ================================================================== */
/* 频谱条 + 卡拉OK + 引擎（v3 保留）                                    */
/* ================================================================== */
function SpectrumBars({ data, theme, maxH = 64, y = 0, opacity = 0.9 }: any) {
  const n = 28;
  const w = 960;
  const bw = w / n;
  return (
    <g opacity={opacity}>
      {Array.from({ length: n }).map((_, i) => {
        const v = data[i] ?? 0.02;
        const h = Math.max(1.5, v * maxH);
        const cx = i * bw + bw / 2;
        return (
          <rect key={i} x={cx - bw * 0.32} y={y - h} width={bw * 0.64} height={h} rx={bw * 0.2} fill={i % 4 === 0 ? theme.accent.primary : i % 2 ? theme.category.cyan : theme.category.purple} />
        );
      })}
    </g>
  );
}

function renderScene(scene: string, theme: any, sp: number[], opacity: number, key: string) {
  return (
    <g key={key} opacity={opacity} style={{ animation: "v2-scenein 1.1s ease-out 0s 1 both" }}>
      {scene === "intro" && <SceneIntro theme={theme} sp={sp} />}
      {scene === "city" && <SceneCity theme={theme} sp={sp} />}
      {scene === "stage" && <SceneStage theme={theme} sp={sp} />}
      {scene === "cape" && <SceneCape theme={theme} sp={sp} />}
      {scene === "paper" && <ScenePaper theme={theme} sp={sp} />}
      {scene === "hoop" && <SceneHoop theme={theme} sp={sp} />}
      {scene === "outro" && <SceneOutro theme={theme} sp={sp} />}
    </g>
  );
}

function KaraText({ line, on, theme }: any) {
  const chars = line.split("");
  const active = Math.floor(on * chars.length);
  return (
    <text x="480" y="508" textAnchor="middle" fontSize="30" fontWeight="600" letterSpacing="2">
      {chars.map((c, i) => (
        <tspan key={i} fill={i < active ? theme.accent.primary : theme.text.primary}>{c}</tspan>
      ))}
    </text>
  );
}

export default function SupermanWontFly() {
  const theme = useHostTheme();
  const [playing, setPlaying] = useState(true);
  const [clock, setClock] = useState(0);
  const [spectrum, setSpectrum] = useState<number[]>([]);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const ctxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  const lineIdx = Math.min(Math.max(LINES.findIndex((l) => clock >= l.t0 && clock < l.t1), 0), LINES.length - 1);
  const line = LINES[lineIdx];
  const finished = clock >= TOTAL;
  const lineProgress = (clock - line.t0) / (line.t1 - line.t0);

  useEffect(() => {
    const a = audioRef.current;
    if (!a || !HAS_AUDIO) return;
    const initAudio = () => {
      try {
        if (!ctxRef.current) {
          const ctx = new AudioContext();
          const src = ctx.createMediaElementSource(a);
          const an = ctx.createAnalyser();
          an.fftSize = 64;
          an.smoothingTimeConstant = 0.8;
          src.connect(an);
          an.connect(ctx.destination);
          ctxRef.current = ctx;
          analyserRef.current = an;
        }
        if (ctxRef.current.state === "suspended") void ctxRef.current.resume();
      } catch { /* 频谱降级 */ }
    };
    a.addEventListener("play", initAudio);
    return () => a.removeEventListener("play", initAudio);
  }, []);

  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => {
      setClock((c) => {
        const a = audioRef.current;
        if (a && a.src && a.duration) return a.currentTime;
        return c + 0.05;
      });
      const an = analyserRef.current;
      if (an) {
        const arr = new Uint8Array(an.frequencyBinCount);
        an.getByteFrequencyData(arr);
        setSpectrum(Array.from(arr).slice(0, 28).map((v) => v / 255));
      }
    }, 50);
    return () => clearInterval(id);
  }, [playing]);

  useEffect(() => {
    if (clock >= TOTAL) setPlaying(false);
  }, [clock]);

  const toggle = () => {
    const a = audioRef.current;
    if (finished) {
      setClock(0);
      setPlaying(true);
      if (a && HAS_AUDIO) { a.currentTime = 0; void a.play().catch(() => {}); }
      return;
    }
    setPlaying(!playing);
    if (a && HAS_AUDIO) {
      if (playing) a.pause();
      else void a.play().catch(() => {});
    }
  };

  const onLine = (l: LyricLine) => {
    const a = audioRef.current;
    setClock(l.t0 + 0.01);
    setPlaying(true);
    if (a && HAS_AUDIO) { a.currentTime = l.t0; void a.play().catch(() => {}); }
  };

  const nextLine = lineIdx < LINES.length - 1 ? LINES[lineIdx + 1] : null;
  const fade = nextLine ? Math.min(Math.max((lineProgress - 0.72) / 0.28, 0), 1) : 0;
  const sp = spectrum.length ? spectrum : [];

  return (
    <Stack gap={20} style={{ padding: 24, background: theme.bg.editor }}>
      <audio
        ref={audioRef}
        src={AUDIO_URL}
        preload="metadata"
        onTimeUpdate={() => { if (playing) setClock(audioRef.current?.currentTime || 0); }}
        onEnded={() => setPlaying(false)}
      />

      <Row justify="space-between" align="center">
        <H1 style={{ margin: 0 }}>超人不会飞 · MV 同步版</H1>
        <Pill active>theme: {theme.kind}</Pill>
      </Row>
      <Text tone="secondary">
        歌词时间轴 + 分镜画面 + 卡拉OK + <b>BGM 内嵌</b>（WebAudio 频谱驱动）· 材质引擎 v4：噪点 / 多层渐变 / 体积光 / 投影
      </Text>

      <Card>
        <CardHeader trailing={<Pill>{SCENE_NAMES[line.scene]}</Pill>}>视频预览</CardHeader>
        <CardBody>
          <Stack gap={12}>
            <svg viewBox="0 0 960 540" width="100%" style={{ display: "block", background: theme.bg.chrome, borderRadius: 4 }} role="img" aria-label="超人不会飞 MV 画面">
              <style>{V2_CSS}</style>
              <MaterialDefs theme={theme} />
              {fade > 0 && nextLine && renderScene(nextLine.scene, theme, sp, fade, "next")}
              {renderScene(line.scene, theme, sp, Math.max(1 - fade * 0.55, 0.45), "cur")}

              <text x="24" y="40" fill={theme.text.tertiary} fontSize="15" letterSpacing="2">
                {Math.floor(clock / 60)}:{String(Math.floor(clock % 60)).padStart(2, "0")} / 1:08
              </text>
              <g key={lineIdx}>
                <rect x="0" y="470" width="960" height="70" fill={theme.bg.editor} opacity="0.8" />
                <KaraText line={line.line} on={Math.min(Math.max(lineProgress, 0), 1)} theme={theme} />
              </g>
              {sp.length > 0 && <SpectrumBars data={sp} theme={theme} maxH={18} y={468} opacity={0.35} />}
            </svg>

            <Row gap={12} align="center">
              <Button variant={playing ? "secondary" : "primary"} onClick={toggle}>
                {finished ? "重播" : playing ? "暂停" : "播放"}
              </Button>
              <div style={{ flex: 1, display: "flex", gap: 2, height: 8, borderRadius: 4, overflow: "hidden", background: theme.fill.tertiary }}>
                {LINES.map((l, i) => {
                  const w = ((l.t1 - l.t0) / TOTAL) * 100;
                  const activeSeg = i === lineIdx;
                  const filled = activeSeg ? ((clock - l.t0) / (l.t1 - l.t0)) * w : i < lineIdx ? w : 0;
                  return (
                    <div key={i} style={{ position: "relative", width: w + "%", height: "100%", background: activeSeg ? theme.fill.primary : theme.fill.tertiary, cursor: "pointer" }} onClick={() => onLine(l)}>
                      <div style={{ position: "absolute", top: 0, left: 0, height: "100%", width: filled + "%", background: theme.accent.primary }} />
                    </div>
                  );
                })}
              </div>
              <Text size="small" tone="secondary" style={{ minWidth: 62, textAlign: "right" }}>
                {Math.floor(clock)}s
              </Text>
            </Row>

            <Stack gap={4}>
              {LINES.map((l, i) => (
                <Row key={i} gap={10} align="center">
                  <Text size="small" tone={i === lineIdx ? "primary" : "tertiary"} style={{ width: 46, fontVariantNumeric: "tabular-nums" }}>
                    {Math.floor(l.t0 / 60)}:{String(Math.floor(l.t0 % 60)).padStart(2, "0")}
                  </Text>
                  <Pill size="sm" active={i === lineIdx}>{SCENE_NAMES[l.scene]}</Pill>
                  <Text size="small" tone={i === lineIdx ? "primary" : "secondary"}>{l.line}</Text>
                  <Spacer />
                  <Button variant="ghost" onClick={() => onLine(l)}>跳转</Button>
                </Row>
              ))}
            </Stack>

            <Text size="small" tone="tertiary">
              BGM 内嵌 · 点播放后 audio.currentTime 驱动画面 · 频谱经 AnalyserNode 实时驱动副歌光环 / 光粒 / 打字机
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Text size="small" tone="tertiary">
        材质引擎 v4：确定性噪点 pattern / 墙面·木纹·金属·玻璃·体积光多层渐变 / feDropShadow 投影 / 透视·纵深·遮挡构图
      </Text>
    </Stack>
  );
}
